from test_config import ROOT,BASE,CHROMIUM,QA_NOW
from playwright.sync_api import sync_playwright
import json,os
fixture=json.loads((ROOT/'tests/fixtures/worker-1.json').read_text());engine=os.getenv('PS_TEST_ENGINE','chromium');out=ROOT/'evidence/gps';out.mkdir(exist_ok=True)
stub='''(()=>{let next=1,active=new Map(),history=new Map(),cleared=[];Object.defineProperty(navigator,'geolocation',{configurable:true,value:{watchPosition(ok,bad,opts){const id=next++;active.set(id,{ok,bad,opts});history.set(id,{ok,bad});return id},clearWatch(id){active.delete(id);cleared.push(id)}}});window.geoTest={active,history,cleared,fix(lat,lng,accuracy=8){for(const v of active.values())v.ok({coords:{latitude:lat,longitude:lng,accuracy},timestamp:Date.now()})},error(code){for(const v of [...active.values()])v.bad({code})}}})()'''
with sync_playwright() as p:
 b=p.chromium.launch(executable_path=CHROMIUM,args=['--no-sandbox']) if engine=='chromium' else p.webkit.launch();c=b.new_context(viewport={'width':390,'height':844},is_mobile=True,timezone_id='Asia/Taipei');c.add_init_script(stub);c.route('https://tile.openstreetmap.org/**',lambda r:r.abort());c.route('**/data/worker-1.json',lambda r:r.fulfill(json=fixture));pg=c.new_page();pg.clock.install(time=QA_NOW);errors=[];posts=[];pg.on('pageerror',lambda e:errors.append(str(e)));pg.on('request',lambda r:posts.append(r.url) if r.method not in ['GET','HEAD'] else None);pg.goto(BASE+'worker-1.html');pg.wait_for_function('PSApp.state.tasks.length===1');assert pg.evaluate('geoTest.active.size')==0
