 def layers():return pg.evaluate("""()=>{const out={};PSApp.map.eachLayer(l=>{if(l.options.gpsLayer)out[l.options.gpsLayer]={lat:l.getLatLng().lat,lng:l.getLatLng().lng,radius:l.getRadius(),color:l.options.fillColor}});return out}""")
 a=layers();assert a['position']['lat']==22.628 and a['accuracy']['radius']==8;assert pg.evaluate('PSApp.map.distance(PSApp.map.getCenter(),[22.628,120.291])')<1
 pg.evaluate('geoTest.fix(22.629,120.292,15)');a=layers();assert a['position']['lat']==22.629 and a['accuracy']['radius']==15;assert pg.evaluate('PSApp.map.distance(PSApp.map.getCenter(),[22.628,120.291])')<1,'Tracking must not hijack map panning';pg.click('#field-locate');assert pg.evaluate('PSApp.map.distance(PSApp.map.getCenter(),[22.629,120.292])')<1;assert pg.locator('#worker-navigate').get_attribute('href')==nav;assert pg.evaluate('JSON.stringify(PSApp.state.tasks)')==task_before;pg.screenshot(path=str(out/f'{engine}-gps.png'))
 # More than a minute without a new fix must not look like a fresh GPS fix.
 pg.clock.fast_forward(75000);assert pg.locator('#field-location-status').get_attribute('data-state')=='stale';assert layers()['position']['color']=='#8796a6';pg.evaluate('geoTest.fix(22.630,120.293,6)');assert pg.locator('#field-location-status').get_attribute('data-state')=='active'
 # Background and BFCache/page transitions stop the watcher and resume only on return.
 pg.evaluate("Object.defineProperty(document,'hidden',{configurable:true,get:()=>true});document.dispatchEvent(new Event('visibilitychange'))");assert pg.evaluate('geoTest.active.size')==0;assert pg.locator('#field-location-status').get_attribute('data-state')=='paused'
 pg.evaluate("Object.defineProperty(document,'hidden',{configurable:true,get:()=>false});document.dispatchEvent(new Event('visibilitychange'))");assert pg.evaluate('geoTest.active.size')==1
 pg.evaluate("window.dispatchEvent(new Event('pagehide'))");assert pg.evaluate('geoTest.active.size')==0;pg.evaluate("window.dispatchEvent(new Event('pageshow'))");assert pg.evaluate('geoTest.active.size')==1
 old_id=pg.evaluate('[...geoTest.active.keys()][0]');pg.click('#field-location-stop');assert pg.evaluate('geoTest.active.size')==0;assert not layers();pg.evaluate('(id)=>geoTest.history.get(id).ok({coords:{latitude:22,longitude:120,accuracy:5},timestamp:Date.now()})',old_id);assert not layers(),'Late GPS fix after stop must be ignored'
 pg.click('#field-locate');pg.evaluate('geoTest.error(1)');assert pg.locator('#field-location-status').get_attribute('data-state')=='denied';assert pg.evaluate('geoTest.active.size')==0;assert not layers();pg.click('#field-locate');pg.evaluate('geoTest.error(3)');assert pg.locator('#field-location-status').get_attribute('data-state')=='error';assert '逾時' in pg.locator('#field-location-status').inner_text();pg.evaluate('geoTest.fix(22.631,120.294,7)');assert pg.locator('#field-location-status').get_attribute('data-state')=='active'
